import React, { useEffect, useState } from 'react'
import { Container, Table } from "react-bootstrap"
import { useNavigate } from 'react-router-dom'
import { ethers } from "ethers"
import { useAccount } from 'wagmi'
import Account from './Account'
import { supportDespoitChains, supportWithdrawChains } from '../../constants/networks'
import { DepositTokens, contracts } from '../../constants/contracts'
import CloseSvg from '../../assets/images/close.svg';

const optimismSDK = require("@eth-optimism/sdk")

const DepositAccount = () => {
    const [loader, setLoader] = useState(false)
    const navigate = useNavigate();

    const { address, isConnected } = useAccount()
    const [depositDetails, setDepositDetails] = useState([])
    const getDeposit = async () => {
        let list = [];
        for (const l1Chain of supportDespoitChains) {
            const l2Chain = supportWithdrawChains.find(({ l1ChainId }) => l1ChainId === l1Chain.id);
            const [l1Url] = l1Chain.rpcUrls.default.http;
            const [l2Url] = l2Chain.rpcUrls.default.http;
            const l1Provider = new ethers.providers.JsonRpcProvider(l1Url);
            const l2Provider = new ethers.providers.JsonRpcProvider(l2Url);
    
            const l1Signer = l1Provider.getSigner()
            const l2Signer = l2Provider.getSigner()
            const l1Contracts = contracts[l1Chain.id];
    
            const bridges = {
                Standard: {
                    l1Bridge: l1Contracts.L1StandardBridge,
                    l2Bridge: l1Contracts.L2Bridge,
                    Adapter: optimismSDK.StandardBridgeAdapter
                },
                ETH: {
                    l1Bridge: l1Contracts.L1StandardBridge,
                    l2Bridge: l1Contracts.L2Bridge,
                    Adapter: optimismSDK.ETHBridgeAdapter
                }
            }
            const crossChainMessenger = new optimismSDK.CrossChainMessenger({
                contracts: {
                    l1: l1Contracts,
                },
                bridges: bridges,
                l1ChainId: l1Chain.id,
                l2ChainId: l2Chain.id,
                l1SignerOrProvider: l1Signer,
                l2SignerOrProvider: l2Signer,
                bedrock: true,
            })
            try {
                const data = await crossChainMessenger.getDepositsByAddress(address)
                for (let index = 0; index < data.length; index++) {
                    let timestamp = data[index].timestamp || (await l1Provider.getBlock(data[index].blockNumber)).timestamp;
                    data[index].timestamp = timestamp;
                    data[index].blockExplorer = l1Chain.blockExplorers.default.url;

                    data[index].tokenSymbol = 'ETH';
                    for (const token of DepositTokens) {
                        if (token.address.toLowerCase() === data[index].l1Token.toLowerCase()) {
                            data[index].tokenSymbol = token.symbol;
                            data[index].decimals = token.decimals;
                        }
                    }
                }
                list = list.concat(data);
            } catch (error) {
                console.log(error);
            }
        }
        list = list.sort((x, y) => y.timestamp - x.timestamp);
        setDepositDetails(list);
        setLoader(true);
    }
    function timeConverter(timestamp) {
        var a = new Date(timestamp * 1000);
        var months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
        var year = a.getFullYear();
        var month = months[a.getMonth()];
        var date = a.getDate();
        var hour = a.getHours();
        var min = a.getMinutes();
        var sec = a.getSeconds();
        var time = date + ' ' + month + ' ' + year + ' ' + hour + ':' + min + ':' + sec;
        return time;
    }

    function retrieveEthValue(amount, decimals = '18') {
        const weiValue = parseInt(amount._hex, 16);
        return weiValue / Number("1".padEnd(+(decimals) + 1, 0));
    }

    useEffect(() => {
        if (isConnected) {
            getDeposit()
        }
    }, [address]);

    // =============all Collections pagination start===============
    // const [pageCountCollections, setPageCountCollections] = useState(0);
    // const [itemOffsetCollections, setItemOffsetCollections] = useState(0);
    // const itemsPerPageCollections = 10;

    // useEffect(() => {
    //     if (depositDetails) {
    //         const endOffsetCollections = itemOffsetCollections + itemsPerPageCollections;
    //         setCurrentItemsCollections(depositDetails.slice(itemOffsetCollections, endOffsetCollections));
    //         setPageCountCollections(Math.ceil(depositDetails.length / itemsPerPageCollections));
    //     } else {

    //     }
    // }, [depositDetails, itemOffsetCollections, itemsPerPageCollections]);

    // const handlePageClickCollections = (event) => {
    //     const newOffsetCollections =
    //         (event.selected * itemsPerPageCollections) % depositDetails.length;
    //     setItemOffsetCollections(newOffsetCollections);
    // };
    // =============all Collections pagination end===============
    // useEffect(() => {
    //     console.log({ depositDetails, currentItemsCollections })
    // }, [depositDetails, currentItemsCollections])
    return (
        <>
            <div className="account_wrap">
                <Container>
                    <div className='account_inner_wrap'>
                        <div className="close-btn" onClick={() => navigate('/deposit')}>
                            <img src={CloseSvg} />
                        </div>
                        <Account />
                        <section className="account_withdraw_table">
                            {
                                !loader ? <div className="lds-ellipsis"><div></div><div></div><div></div><div></div></div> : depositDetails?.length <= 0 ? <h4 className='text-center text-white'>No Transaction Found</h4> :
                                    <Table responsive bordered hover variant="dark">
                                        <thead>
                                            <tr>
                                                <th>Time</th>
                                                <th>Type</th>
                                                <th>Amount</th>
                                                <th>Transaction</th>
                                                <th>Status</th>
                                            </tr>
                                        </thead>
                                        <tbody>
                                            {depositDetails.map((element, index) => {
                                                const { timestamp, transactionHash, amount, blockExplorer, tokenSymbol, decimals } = element
                                                // console.log("amount", tokenList.filter(a => a.type === l1Token)[0]?.tokenSymbol);
                                                return (
                                                    <tr key={index}>
                                                        <td>{timeConverter(timestamp)}</td>
                                                        <td>Deposit</td>
                                                        <td>{retrieveEthValue(amount, decimals)} {tokenSymbol}</td>
                                                        <td> <a href={`${blockExplorer}/tx/${transactionHash}`} target='_blank'> {`${transactionHash.slice(0, 8)}...${transactionHash.slice(-8)}`}</a></td>
                                                        <td>Completed</td>
                                                    </tr>
                                                )
                                            })}
                                        </tbody>
                                    </Table>}
                            {/* {depositDetails?.length > 10 ? <div className='pagination_wrap'>
                                <ReactPaginate
                                    breakLabel="..."
                                    nextLabel=" >>"
                                    onPageChange={handlePageClickCollections}
                                    pageRangeDisplayed={1}
                                    marginPagesDisplayed={1}
                                    pageCount={pageCountCollections}
                                    previousLabel="<< "
                                    containerClassName="pagination justify-content-end"
                                    pageClassName="page-item"
                                    pageLinkClassName="page-link"
                                    previousClassName="page-item"
                                    previousLinkClassName="page-link"
                                    nextClassName="page-item"
                                    nextLinkClassName="page-link"
                                    breakClassName="page-item"
                                    breakLinkClassName="page-link"
                                    activeClassName="active"
                                />
                            </div> : ""} */}
                        </section>
                    </div>
                </Container>
            </div>
        </>
    )
}

export default DepositAccount