import { useEffect, useRef, useState } from "react"
import { Spinner } from "react-bootstrap";

const messageMap = {
    6: 'Completed',
    5: 'Claim Withdrawal',
    4: 'In challenge Period',
    3: 'Ready to Prove',
    2: 'Waiting for Confirmation',
}

const WithdrawButton = ({ loading, messageStatus, handleProve, handleClaim, updateStatus }) => {
  const [status, setStatus] = useState(messageStatus);
  const timer = useRef(null);
  const renderButton = () => {
    if (loading) {
      return (
        <button type='button' className='btn withdraw_inner_btn' >
            <Spinner animation="border" role="status">
                <span className="visually-hidden">Loading...</span>
            </Spinner>
        </button>
      )
    }
    if (status === 3) {
      return (
        <button type='button' className='btn withdraw_inner_btn' onClick={handleProve}>
            Prove
        </button>
      );
    }
    if (status === 5) {
      return (
        <button type='button' className='btn withdraw_inner_btn' onClick={handleClaim}>
            Claim
        </button>
      )
    }
    return null;
  }

  const handleTimer = () => {
    clearInterval(timer.current);
    if ([2, 4].includes(status)) {
      timer.current = setInterval(() => {
        updateStatus().then(newStatus => {
          if (newStatus !== status) {
            setStatus(newStatus);
          }
        })
      }, 10000);
    }
  }

  useEffect(() => {
    handleTimer();
  }, [status]);

  useEffect(() => {
    return () => {
      clearInterval(timer.current);
    }
  }, []);

  return (
    <>
      {messageMap[status]}
      {renderButton()}
    </>
  );
}

export default WithdrawButton;
