import React, { useMemo, useState } from 'react';
import "../assets/style/deposit.scss";
import "../assets/style/withdraw.scss";
import { Image, Spinner, Form } from "react-bootstrap";
import toIcn from "../assets/images/logo-icon.svg"
import { useAccount, useConnect, useNetwork, useSwitchNetwork, useBalance } from 'wagmi'
import { InjectedConnector } from 'wagmi/connectors/injected';
import { HiSwitchHorizontal } from "react-icons/hi";
import metamask from "../assets/images/metamask.svg"
import TabMenu from './TabMenu';
import WithdrawTitleIcon from '../assets/images/withdraw-title.svg';
import walletIcn from '../assets/images/wallet.svg';
import { supportDespoitChains, supportWithdrawChains } from '../constants/networks';
import { numberToHex } from 'viem';
import { Tokens, WithdrawTokens, contracts } from '../constants/contracts';
import useAccountBalance from '../hooks/useAccountBalance';

const optimismSDK = require("@eth-optimism/sdk")
const ethers = require("ethers")

const Withdraw = () => {
  const [ethValue, setEthValue] = useState("")
  const [sendToken, setSendToken] = useState(WithdrawTokens[0].name)
  const [errorInput, setErrorInput] = useState("")
  const [checkMetaMask, setCheckMetaMask] = useState("");
  const [loader, setLoader] = useState(false)
  const { address, isConnected } = useAccount()
  const { chain, chains } = useNetwork()
  const { connect } = useConnect({
    connector: new InjectedConnector({ chains }), onError(error) {
      console.log('Error', error)
    },
    onMutate(args) {
      console.log('Mutate', args)
      if (args.connector.ready === true) {
        setCheckMetaMask(false)
      } else {
        setCheckMetaMask(true)
      }
    },
    onSettled(data, error) {
      console.log('Settled', { data, error })
    },
    onSuccess(data) {
      console.log('Success', data)
    },
  })
  const [metaMastError, setMetaMaskError] = useState("")
  const balance = useAccountBalance();

  const { switchNetworkAsync } = useSwitchNetwork({
      onSuccess: () => {
          setEthValue("");
          setErrorInput("");
          setCheckDisabled(false);
      }
  })
  //========================================================== BALANCES =======================================================================

  // const b2Gp = useBalance({ address: address, token: GPCoin[supportWithdrawChains[0].id], watch: true, chainId: supportWithdrawChains[0].id })
  // const lineaGp = useBalance({ address: address, token: GPCoin[supportWithdrawChains[1].id], watch: true, chainId: supportWithdrawChains[1].id })

  ////========================================================== WITHDRAW =======================================================================

  const handleWithdraw = async () => {
    try {
      if (!ethValue) {
        setErrorInput("Please enter the amount");
      }
      else {
        if (!parseFloat(ethValue) > 0) {
          setErrorInput("Invalid Amount Entered!");
        } else {
          setErrorInput("");
          const l2Chain = supportWithdrawChains.find(({ id }) => id === chain.id);
          const l1Chain = supportDespoitChains.find(({ id }) => id === l2Chain.l1ChainId);
          const [l1Url] = l1Chain.rpcUrls.default.http;

          const l1Provider = new ethers.providers.JsonRpcProvider(l1Url, "any");
          const l2Provider = new ethers.providers.Web3Provider(window.ethereum);

          const l1Signer = l1Provider.getSigner(address);
          const l2Signer = l2Provider.getSigner(address);
          const l1Contracts = contracts[l1Chain.id];

          const bridges = {
              Standard: {
                  l1Bridge: l1Contracts.L1StandardBridge,
                  l2Bridge: l1Contracts.L2Bridge,
                  Adapter: optimismSDK.StandardBridgeAdapter
              },
              ETH: {
                  l1Bridge: l1Contracts.L1StandardBridge,
                  l2Bridge: l1Contracts.L2Bridge,
                  Adapter: optimismSDK.ETHBridgeAdapter
              }
          }
          const crossChainMessenger = new optimismSDK.CrossChainMessenger({
              contracts: {
                l1: l1Contracts,
              },
              bridges: bridges,
              l1ChainId: l1Chain.id,
              l2ChainId: l2Chain.id,
              l1SignerOrProvider: l1Signer,
              l2SignerOrProvider: l2Signer,
              bedrock: true,
          })
          //-------------------------------------------------------- SEND TOKEN VALUE -----------------------------------------------------------------

          try {
            if (sendToken == "eth") {
              const weiValue = parseInt(ethers.utils.parseEther(ethValue)._hex, 16)
              setLoader(true);
              const response = await crossChainMessenger.withdrawETH(weiValue.toString());
              const logs = await response.wait();
              if (logs) {
                setLoader(false);
                setEthValue("");
              }
            } else {
              // GP, others..

              const gpValue = ethers.utils.parseUnits(ethValue, balance[l2Chain.id][sendToken].data.decimals).toString()
              // const gpValue = Web3.utils.toWei(ethValue, 'ether');
              setLoader(true);
              const l1TokenAddress = Tokens[sendToken.toUpperCase()][l1Chain.id].address;
              const l2TokenAddress = Tokens[sendToken.toUpperCase()][l2Chain.id].address;
              const withdrawTxn = await crossChainMessenger.withdrawERC20(l1TokenAddress, l2TokenAddress, gpValue);
              const receiptGp = await withdrawTxn.wait()
              if (receiptGp) {
                setLoader(false);
                setEthValue("")
              }
            }
            //-------------------------------------------------------- SEND TOKEN VALUE END-----------------------------------------------------------------
            // updateGpBalance()
          }
          catch (error) {
            setLoader(false);
            console.log({ error }, 98);
          }
        }
      }

    } catch (error) {
      console.log(error);
    }
  }

  const handleSwitch = async (chainId = supportWithdrawChains[0].id) => {
    console.log('chainId:', chainId);
    try {
        await switchNetworkAsync(chainId);
    } catch (error) {
      const needAddChain = error.message.includes('rpcUrls') || error.message.includes('not configured');
        if (needAddChain) {
            for (const chainInfo of supportWithdrawChains) {
                if (chainInfo.id === chainId) {
                  console.log(chainInfo);
                    window.ethereum.request({
                        method: "wallet_addEthereumChain",
                        params: [{
                          chainId: numberToHex(chainInfo.id),
                          rpcUrls: [chainInfo.rpcUrls.default.http[0]],
                          chainName: chainInfo.name,
                          nativeCurrency: chainInfo.nativeCurrency,
                          blockExplorerUrls: [chainInfo.blockExplorers.default.url]
                        }]
                    })
                        .then(() => switchNetworkAsync(chainId))
                        .catch((error) => console.log(error))
                }
            }
        }
    }
}
  ////========================================================== HANDLE CHANGE =======================================================================
  const [checkDisabled, setCheckDisabled] = useState(false)

  const handleChange = (e) => {

    if (Number(balance[chain.id][sendToken].data?.formatted) < e.target.value) {
        setErrorInput(`Insufficient balance.`)
        setCheckDisabled(true)
    } else {
        setCheckDisabled(false)
        setErrorInput("")
    }
    setEthValue(e.target.value)
  }

  // ============= Get and update balance =========================
  // const updateGpBalance = async () => {
  //   // const balance = formatBalance(await window.ethereum.request({
  //   //   method: "eth_getBalance",
  //   //   params: [address, "latest"]
  //   // }))
  // }

  const renderButton = () => {
    if (checkMetaMask) {
        return (
            <a className='btn deposit_btn' href='https://metamask.io/' target='_blank'>
                <Image src={metamask} alt="metamask icn" fluid /> Please Install Metamask Wallet
            </a>
        );
    }
    if (!isConnected) {
        return (
            <button className='btn deposit_btn' onClick={() => connect()}>
                <img src={walletIcn} />Connect Wallet
            </button>
        )
    }
    if (!supportWithdrawChains.map(chain => chain.id).includes(chain?.id)) {
        return (
            <button className='btn deposit_btn' onClick={() => handleSwitch()}>
                <HiSwitchHorizontal />Switch to Zytron Linea
            </button>
        )
    }
    if (checkDisabled) {
        return <button className='btn deposit_btn' disabled={true}>Withdraw</button>;
    }

    return (
        <button className='btn deposit_btn' onClick={handleWithdraw} disabled={loader ? true : false}>
            {loader ? <Spinner animation="border" role="status"><span className="visually-hidden">Loading...</span></Spinner> : "Withdraw"}
        </button>
    )
  }

  const destChain = useMemo(() => {
    for (const network of supportWithdrawChains) {
      if (network.id === chain?.id) {
        return supportDespoitChains.find(chain => chain.id === network.l1ChainId).name;
      }
    }
    return '--';
  }, [chain]);

  const sendTokenSymbol = useMemo(() => (WithdrawTokens.find(token => token.name === sendToken) || {}).symbol || '', [sendToken]);

  return (
    <>
      <div className='bridge_wrap'>
        <TabMenu />
        <section className='deposit_wrap'>
          <div className='withdraw_title_wrap'>
            <div className="withdraw_title_body">
              <img src={WithdrawTitleIcon} />
              <div>
                <div className="withdraw_title_header">Use the official bridge</div>
                <div className="withdraw_title_desc">
                  <p>This usually takes 7 days</p>
                  <p>Bridge any token to {destChain}</p>
                </div>
              </div>
            </div>
          </div>
          <div className='deposit_price_wrap'>
            <div className='deposit_price_title'>
              <p>From</p>
              <div className="select-networks">
                  <div className="active">
                      <img src={toIcn} />
                      <div>Zytron L3</div>
                  </div>
              </div>
            </div>
            <div className='deposit_input_wrap'>
                <div className="deposit_input_body">
                    <div className={`${sendToken}-icon`} />
                    <input type='number' value={ethValue} onChange={handleChange} placeholder="0" min="0" step="any" />
                    <Form.Select className='gp-label' onChange={({ target }) => setSendToken(target.value)}>
                      {WithdrawTokens.map(token => (
                        <option key={token.symbol} value={token.name}>{token.symbol}</option>
                      ))}
                    </Form.Select>
                </div>
            </div>
            {address && supportWithdrawChains.find(({ id }) => chain?.id === id) && (
                <p className='wallet_bal mt-2'>
                  {`Balance: ${Number(balance[chain.id][sendToken].data?.formatted).toFixed(5)} ${sendTokenSymbol}`}
                </p>
            )}
          </div>
          <div className='deposit_details_wrap'>
            <div className="deposit_details">
              <p>To:</p>
              <div className="select-networks">
                {supportWithdrawChains.map(({ id, l1ChainId }) => (
                  <div className={chain?.id === id ? 'active' : ''} onClick={() => handleSwitch(id)} key={id}>
                    {supportDespoitChains.find(dpChain => dpChain.id === l1ChainId).name}
                  </div>
                ))}
              </div>
            </div>
            <div className='receive-detail'>
                <div className={`${sendToken}-icon relative`} />
                You’ll receive: {ethValue ? ethValue : "0"} {sendTokenSymbol}
            </div>
          </div>
          <div className="actions-wrap">
            {renderButton()}
          </div>
          {metaMastError && <small className="d-block text-danger text-center mt-2">{metaMastError}</small>}
        </section>
      </div>
    </>
  )
}

export default Withdraw