import { BrowserRouter, Routes, Route } from "react-router-dom";
import Header from "./components/common/Header";
import Footer from "./components/common/Footer";
import Deposit from './components/Deposit';
import Withdraw from './components/Withdraw';
import WithdrawAccount from "./components/account/WithdrawAccount";
import DepositAccount from "./components/account/DepositAccount";
function App() {
  console.log('REACT_APP_LINEA_OPTIMISM_PORTAL_PROXY:', process.env.REACT_APP_LINEA_OPTIMISM_PORTAL_PROXY)
  console.log('REACT_APP_LINEA_LIB_ADDRESSMANAGER:', process.env.REACT_APP_LINEA_LIB_ADDRESSMANAGER);
  console.log('REACT_APP_LINEA_PROXY_OVM_L1CROSSDOMAINMESSENGER:', process.env.REACT_APP_LINEA_PROXY_OVM_L1CROSSDOMAINMESSENGER);
  console.log('REACT_APP_LINEA_PROXY_OVM_L1STANDARDBRIDGE:', process.env.REACT_APP_LINEA_PROXY_OVM_L1STANDARDBRIDGE);
  console.log('REACT_APP_LINEA_L2_OUTPUTORACLE_PROXY:', process.env.REACT_APP_LINEA_L2_OUTPUTORACLE_PROXY);
  console.log('REACT_APP_LINEA_L2_BRIDGE:', process.env.REACT_APP_LINEA_L2_BRIDGE);
  return (
    <>
      <BrowserRouter>
        <div className="main_wrap">
          <Header />
          <Routes>
            <Route path="/" element={<Deposit />} />
            <Route path="/deposit" element={<Deposit />} />
            <Route path="/withdraw" element={<Withdraw />} />
            <Route path="/account/deposit" element={<DepositAccount />} />
            <Route path="/account/withdraw" element={<WithdrawAccount />} />
          </Routes>
          <Footer />
        </div>
      </BrowserRouter>
    </>
  );
}

export default App;
